Save the following within  your custom plugin for the
size
aspect.  You can do this by making it a notepad file and changing the extension to .js if you do not have a capable editor.   Modifying it as needed adding or subtracting the value of the lines.  The "-225" in the ww line, for example,  tells rpg maker to shorten the right side of the help window by 225 pixels.   If you place "your" custom plugin under/lower than a visustella plugin, it will usually override or modify it... which is handy.
// Override - change height of battle scene's help area.
Scene_Battle.prototype.helpAreaHeight = function() {
return this.calcWindowHeight(2, false);
};
// Override - change width of battle scene's help area.
Scene_Battle.prototype.helpWindowRect = function() {
const wx = 0;
const wy = this.helpAreaTop();
const ww = Graphics.boxWidth -225;
const wh = this.helpAreaHeight();
return new Rectangle(wx, wy, ww, wh);
};

